// ============================================================
// font_cn.v - 16x16 bitmap font for the CJK characters used by
//             the status panel.  GENERATED FILE - do not edit.
//             Regenerate with:  tools/gen_cn_font.py
//
// Source font : simsun.ttc @ 16 px (ink-box centred, >=110 = ink)
// Encoding    : screen code 8'h80+index; bit 15 of a row is the
//               leftmost pixel; row 0 is the top row.
//
// Only the 45 glyphs the panel needs are stored. A full HZK16 would
// not fit: BSRAM is already 46/46, so this ROM is deliberately
// small enough to be built out of LUTs.
// ============================================================
`default_nettype none

module font_cn (
    input  wire [5:0] idx,    // 0..44  (screen code 8'h80 + idx)
    input  wire [3:0] row,    // 0..15, 0 = top
    output wire [15:0] dout   // MSB = leftmost pixel
);

    reg [255:0] g;            // 16 rows x 16 bits

