    // row 0 lives in the top 16 bits.
    // OFFSET MUST BE BUILT BY CONCAT: a shift like (4'd15 - row) << 4
    // self-determines to 4 bits, so the offset is always 0 (mod 16)
    // and every glyph renders as its bottom row. Keep the
    // concatenation form so the offset stays width-correct.
    wire [3:0]  rinv = 4'd15 - row;
    wire [11:0] roff = {8'd0, rinv, 4'd0};   // (15-row)*16
    assign dout = g >> roff;                 // low 16 bits used

endmodule
`default_nettype wire
